//! G02 slice 2 (`ffw-ld0`): known multichannel PCM through D02 while the controls change mid-stream.
//!
//! `tests/g02/pcm_vectors.json` is generated by the independent Python reference
//! (`tests/g02/pcm_generate.py`), never by this crate. Every case streams the documented LCG samples,
//! one frame at a time, through three real `ProtectedBoardDsp` instances:
//!
//! * **B**, the controlled board: a `MemberVolume` applies the case's frame-exact schedule (group
//!   volume, local buttons, mutes, membership) and `sync`s the board before each affected frame;
//! * **A**, the unity-gain reference: unmuted at gain 1.0 for the whole stream, fed the same samples;
//! * **R**, the role check: unity gain, fed the pre-mapped stream computed here with the contract's
//!   formulas instead of `RolePlan`.
//!
//! Filters, DC rejection and fades are identical in A and B (they depend only on the input), so the
//! controlled output must equal the unity-gain output scaled by the applied-gain ratio at every frame.
//! That holds only below the limiter and thermal models, which the run certifies.
//!
//! The harness prints one `G02PCM-OBSERVED {json}` line per case for the Python judge
//! (`tests/g02/pcm_run.py --judge`) and runs the same checks itself, so a violation fails
//! `cargo test`. Override the vector path with `FFW_G02_PCM_VECTORS`.

use franken_board_profile::{BoardProfile, synthetic_test_fixture_catalog};
use franken_dsp::StereoAudioBlock;
use franken_dsp::protection::{
    Admission, ProtectedBoardDsp, ProtectedOutput, synthetic_calibration_for,
};
use franken_dsp::volume::{
    GroupSnapshot, MemberVolume, Role, RolePlan, Stamp, VolumeCommand, VolumeError,
};
use serde_json::{Value, json};
use std::collections::BTreeMap;

const AMPLITUDE: f32 = 0.25;
/// |out_B - out_A * gain_B/gain_A| <= 0.5 (rounding B) + 0.5 (rounding A, scaled by a ratio <= 1)
/// + 0.01 (f32 products at up to 16384 LSB). `f32_to_s16` is `round_ties_even`.
const LINEAR_TOLERANCE_LSB: f64 = 1.01;
const GAIN_TOLERANCE: f64 = 1.0e-7;
/// A reference channel quieter than this over the whole stream would make its checks vacuous.
const MIN_REFERENCE_PEAK_LSB: i32 = 50;
/// The linear regime requires every output to stay clear of the limiter threshold (0.8).
const MAX_OUTPUT_LSB: i32 = 26_214;
const FNV_OFFSET: u64 = 0xcbf2_9ce4_8422_2325;
const FNV_PRIME: u64 = 0x0100_0000_01b3;

fn field<'a>(value: &'a Value, key: &str) -> &'a Value {
    value
        .get(key)
        .unwrap_or_else(|| panic!("vector field `{key}` is missing"))
}

fn str_of<'a>(value: &'a Value, key: &str) -> &'a str {
    field(value, key)
        .as_str()
        .unwrap_or_else(|| panic!("vector field `{key}` is not a string"))
}

fn u64_of(value: &Value, key: &str) -> u64 {
    field(value, key)
        .as_u64()
        .unwrap_or_else(|| panic!("vector field `{key}` is not an unsigned integer"))
}

fn usize_of(value: &Value, key: &str) -> usize {
    usize::try_from(u64_of(value, key)).unwrap_or_else(|_| panic!("`{key}` does not fit usize"))
}

fn arg(items: &[Value], index: usize) -> &Value {
    items
        .get(index)
        .unwrap_or_else(|| panic!("operation is missing argument {index}: {items:?}"))
}

fn u64_at(items: &[Value], index: usize) -> u64 {
    arg(items, index)
        .as_u64()
        .unwrap_or_else(|| panic!("argument {index} is not an unsigned integer: {items:?}"))
}

fn u8_at(items: &[Value], index: usize) -> u8 {
    u8::try_from(u64_at(items, index)).unwrap_or_else(|_| panic!("argument {index} is not a u8"))
}

fn i16_at(items: &[Value], index: usize) -> i16 {
    let n = arg(items, index)
        .as_i64()
        .unwrap_or_else(|| panic!("argument {index} is not an integer: {items:?}"));
    i16::try_from(n).unwrap_or_else(|_| panic!("argument {index} is not an i16"))
}

fn bool_at(items: &[Value], index: usize) -> bool {
    arg(items, index)
        .as_bool()
        .unwrap_or_else(|| panic!("argument {index} is not a boolean: {items:?}"))
}

fn fixture(model: &str) -> BoardProfile {
    synthetic_test_fixture_catalog()
        .into_iter()
        .find(|profile| profile.model_number == model)
        .unwrap_or_else(|| panic!("no synthetic fixture board `{model}`"))
}

fn admit(profile: &BoardProfile) -> ProtectedBoardDsp {
    let calibration = synthetic_calibration_for(profile);
    ProtectedBoardDsp::admit(profile, Some(&calibration), Admission::HostSimulation)
}

/// A ceiling is a number, or the strings "nan"/"inf" because JSON has no non-finite numbers.
fn ceiling_of(value: &Value) -> f32 {
    match value {
        Value::String(text) => match text.as_str() {
            "nan" => f32::NAN,
            "inf" => f32::INFINITY,
            other => panic!("unknown ceiling literal `{other}`"),
        },
        other => other.as_f64().expect("a ceiling is a number") as f32,
    }
}

fn role_of(name: &str) -> Role {
    match name {
        "stereo" => Role::Stereo,
        "left" => Role::Left,
        "right" => Role::Right,
        "sub" => Role::Sub,
        other => panic!("unknown role `{other}`"),
    }
}

/// The contract's remap, written out here independently of `RolePlan`.
fn premap(role: Role, left: f32, right: f32) -> (f32, f32) {
    match role {
        Role::Stereo => (left, right),
        Role::Left => (left, left),
        Role::Right => (right, right),
        Role::Sub => {
            let mid = 0.5 * (left + right);
            (mid, mid)
        }
    }
}

fn command_of(raw: &Value) -> VolumeCommand {
    let items = raw.as_array().expect("a command is an array");
    match items[0].as_str().expect("command name") {
        "set_volume" => VolumeCommand::SetVolume(u8_at(items, 1)),
        "adjust_volume" => VolumeCommand::AdjustVolume(i16_at(items, 1)),
        "set_trim" => VolumeCommand::SetTrim(
            u16::try_from(u64_at(items, 1)).unwrap_or_else(|_| panic!("trim is not a u16")),
        ),
        "reset_trim" => VolumeCommand::ResetTrim,
        "set_group_mute" => VolumeCommand::SetGroupMute(bool_at(items, 1)),
        other => panic!("unknown command `{other}`"),
    }
}

fn code<T>(result: Result<T, VolumeError>) -> &'static str {
    match result {
        Ok(_) => "ok",
        Err(error) => error.code(),
    }
}

/// One scheduled control operation (`op[0]` is its name).
fn apply_op(member: &mut MemberVolume, op: &[Value]) -> &'static str {
    match op[0].as_str().expect("operation name") {
        "declare" => code(member.declare_epoch(u64_at(op, 1))),
        "join" => {
            member.complete_join();
            "ok"
        }
        "cmd" => {
            let stamp = Stamp {
                epoch: u64_at(op, 1),
                revision: u64_at(op, 2),
            };
            code(member.apply(stamp, command_of(arg(op, 3))))
        }
        "local_mute" => {
            member.local_mute(bool_at(op, 1));
            "ok"
        }
        "local_trim" => code(member.local_trim_step(i16_at(op, 1))),
        "ceiling" => {
            member.set_protection_ceiling(ceiling_of(arg(op, 1)));
            "ok"
        }
        "fault_ceiling" => {
            let value = arg(op, 1);
            member.set_fault_ceiling((!value.is_null()).then(|| ceiling_of(value)));
            "ok"
        }
        "reconnect" => code(member.reconnect(GroupSnapshot {
            epoch: u64_at(op, 1),
            revision: u64_at(op, 2),
            master_volume: u8_at(op, 3),
            group_mute: bool_at(op, 4),
        })),
        other => panic!("unknown scheduled operation `{other}`"),
    }
}

/// `state = state * 1664525 + 1013904223 (mod 2^32)`; the sample is `(state >> 16)` as an `i16`.
struct Lcg(u32);

impl Lcg {
    fn next_sample(&mut self) -> f32 {
        self.0 = self.0.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        let raw = (self.0 >> 16) as u16 as i16;
        f32::from(raw) / 32768.0 * AMPLITUDE
    }
}

fn fnv_update(mut state: u64, bytes: &[u8]) -> u64 {
    for &byte in bytes {
        state ^= u64::from(byte);
        state = state.wrapping_mul(FNV_PRIME);
    }
    state
}

fn one_frame(start: usize, left: f32, right: f32) -> StereoAudioBlock {
    let mut block = StereoAudioBlock::silence(start as u64);
    block.frames = 1;
    block.left[0] = left;
    block.right[0] = right;
    block
}

/// Everything one case produced, as plain data (so a planted corruption can be tested).
#[derive(Clone)]
struct Run {
    frames: usize,
    channels: usize,
    input_fnv: String,
    gain_a: Vec<f64>,
    gain_b: Vec<f64>,
    out_a: Vec<i16>,
    out_b: Vec<i16>,
    results: Vec<Value>,
    role_mismatches: u64,
    limiter_min: f64,
    thermal_scaled: u64,
    clipped: u64,
}

fn run_case(case: &Value) -> Run {
    let profile = fixture(str_of(case, "board"));
    let channels = usize::from(profile.hardware_channels);
    let role = role_of(str_of(case, "role"));
    let plan = RolePlan::for_profile(&profile, role).expect("the role exists on this board");
    let frames = usize_of(case, "frames");

    // The synthetic calibration the slice relies on: unity trim and unity max gain on every channel.
    for channel in &synthetic_calibration_for(&profile).channels {
        assert!(
            channel.trim == 1.0 && channel.max_gain == 1.0,
            "the PCM oracle assumes unity trim and max_gain; {:?} has {} / {}",
            channel.role,
            channel.trim,
            channel.max_gain
        );
    }

    let (mut board_a, mut board_b, mut board_r) =
        (admit(&profile), admit(&profile), admit(&profile));
    for reference in [&mut board_a, &mut board_r] {
        reference.set_user_gain(1.0);
        reference.set_muted(false).expect("an active board unmutes");
    }
    let mut member = MemberVolume::new(ceiling_of(field(case, "ceiling")));

    let mut schedule: BTreeMap<usize, Vec<&[Value]>> = BTreeMap::new();
    for entry in field(case, "schedule").as_array().expect("schedule") {
        let items = entry.as_array().expect("a schedule entry is an array");
        let frame = usize::try_from(items[0].as_u64().expect("frame")).expect("frame fits usize");
        schedule.entry(frame).or_default().push(&items[1..]);
    }

    let (mut lcg_left, mut lcg_right) = (
        Lcg(u32::try_from(u64_of(case, "seed_left")).expect("seed fits u32")),
        Lcg(u32::try_from(u64_of(case, "seed_right")).expect("seed fits u32")),
    );
    let (mut out_a, mut out_b, mut out_r) = (
        ProtectedOutput::new(),
        ProtectedOutput::new(),
        ProtectedOutput::new(),
    );
    let mut run = Run {
        frames,
        channels,
        input_fnv: String::new(),
        gain_a: Vec::with_capacity(frames),
        gain_b: Vec::with_capacity(frames),
        out_a: Vec::with_capacity(frames * channels),
        out_b: Vec::with_capacity(frames * channels),
        results: Vec::new(),
        role_mismatches: 0,
        limiter_min: 1.0,
        thermal_scaled: 0,
        clipped: 0,
    };
    let mut fnv = FNV_OFFSET;
    for frame in 0..frames {
        if let Some(ops) = schedule.get(&frame) {
            for op in ops {
                let result = apply_op(&mut member, op);
                let mute = member
                    .effective_mute()
                    .map_or(Value::Null, |reason| json!(reason.name()));
                run.results.push(json!([frame, op[0], result, mute]));
            }
            member.sync(&mut board_b).expect("sync");
        }
        let (left, right) = (lcg_left.next_sample(), lcg_right.next_sample());
        let fed = plan.map(left, right);
        fnv = fnv_update(fnv, &fed.0.to_le_bytes());
        fnv = fnv_update(fnv, &fed.1.to_le_bytes());
        let pre = premap(role, left, right);

        let reports = [
            board_a.render_into(&one_frame(frame, fed.0, fed.1), &mut out_a),
            board_b.render_into(&one_frame(frame, fed.0, fed.1), &mut out_b),
            board_r.render_into(&one_frame(frame, pre.0, pre.1), &mut out_r),
        ];
        for report in reports {
            run.limiter_min = run.limiter_min.min(f64::from(report.min_limiter_gain));
            run.thermal_scaled += u64::from(report.thermal_scaled_samples);
            run.clipped += u64::from(report.clipped_samples);
        }
        run.gain_a.push(f64::from(board_a.applied_gain()));
        run.gain_b.push(f64::from(board_b.applied_gain()));
        for ((lane_a, lane_b), lane_r) in out_a
            .samples
            .iter()
            .zip(&out_b.samples)
            .zip(&out_r.samples)
            .take(channels)
        {
            run.out_a.push(lane_a[0]);
            run.out_b.push(lane_b[0]);
            run.role_mismatches += u64::from(lane_a[0] != lane_r[0]);
        }
    }
    run.input_fnv = format!("{fnv:016x}");
    run
}

fn observation(case: &Value, run: &Run) -> Value {
    json!({
        "id": str_of(case, "id"),
        "kind": "pcm_script",
        "frames": run.frames,
        "channels": run.channels,
        "input_fnv": run.input_fnv,
        "gain_a": run.gain_a,
        "gain_b": run.gain_b,
        "out_a": run.out_a,
        "out_b": run.out_b,
        "results": run.results,
        "role_mismatches": run.role_mismatches,
        "regime": {
            "limiter_min": run.limiter_min,
            "thermal_scaled": run.thermal_scaled,
            "clipped": run.clipped,
        },
    })
}

// ---- checks ---------------------------------------------------------------------------------------------------

fn linearity(run: &Run) -> Option<String> {
    let frames = run
        .out_a
        .chunks_exact(run.channels)
        .zip(run.out_b.chunks_exact(run.channels))
        .zip(run.gain_a.iter().zip(&run.gain_b))
        .enumerate();
    for (frame, ((lane_a, lane_b), (&gain_a, &gain_b))) in frames {
        let ratio = gain_b / gain_a;
        for (channel, (&a, &b)) in lane_a.iter().zip(lane_b).enumerate() {
            let want = f64::from(a) * ratio;
            if (f64::from(b) - want).abs() > LINEAR_TOLERANCE_LSB {
                return Some(format!(
                    "frame {frame} channel {channel}: output {b}, unity output {a} x ratio {ratio} = {want}"
                ));
            }
        }
    }
    None
}

fn silence(run: &Run) -> Option<String> {
    run.out_b
        .chunks_exact(run.channels)
        .zip(&run.gain_b)
        .enumerate()
        .find(|(_, (lane, gain))| **gain == 0.0 && lane.iter().any(|&s| s != 0))
        .map(|(frame, _)| {
            format!("frame {frame}: the applied gain is 0 but a channel is not silent")
        })
}

fn regime(run: &Run) -> Option<String> {
    if run.limiter_min != 1.0 || run.thermal_scaled != 0 || run.clipped != 0 {
        return Some(format!(
            "the linear regime is not certified: limiter min {}, thermal scaled {}, clipped {}",
            run.limiter_min, run.thermal_scaled, run.clipped
        ));
    }
    let loudest = run
        .out_a
        .iter()
        .chain(&run.out_b)
        .map(|&s| i32::from(s).abs())
        .max()
        .unwrap_or(0);
    (loudest > MAX_OUTPUT_LSB)
        .then(|| format!("an output of {loudest} LSB is too close to the limiter"))
}

fn reference_peaks(run: &Run) -> Option<String> {
    for channel in 0..run.channels {
        let peak = run
            .out_a
            .iter()
            .skip(channel)
            .step_by(run.channels)
            .map(|&s| i32::from(s).abs())
            .max()
            .unwrap_or(0);
        if peak < MIN_REFERENCE_PEAK_LSB {
            return Some(format!(
                "channel {channel} peaks at {peak} LSB in the reference run: its checks would be vacuous"
            ));
        }
    }
    None
}

fn pairs(case: &Value, run: &Run) -> Option<String> {
    let expect = field(case, "pair_expect").as_str()?;
    for pair in field(case, "pairs").as_array().expect("pairs") {
        let (i, j) = (
            usize::try_from(pair[0].as_u64().expect("channel")).expect("channel"),
            usize::try_from(pair[1].as_u64().expect("channel")).expect("channel"),
        );
        let differing = run
            .out_a
            .chunks_exact(run.channels)
            .filter(|lane| lane[i] != lane[j])
            .count();
        match expect {
            "equal" if differing != 0 => {
                return Some(format!(
                    "channels {i} and {j} differ in {differing} frames, but a {} room plays one channel on both",
                    str_of(case, "role")
                ));
            }
            "differ" if differing <= run.frames / 4 => {
                return Some(format!(
                    "channels {i} and {j} differ in only {differing} frames: the stereo control is vacuous"
                ));
            }
            _ => {}
        }
    }
    None
}

fn against_expectation(case: &Value, run: &Run) -> Option<String> {
    let expect = field(case, "expect");
    if str_of(expect, "input_fnv") != run.input_fnv {
        return Some(format!(
            "the fed stream is fingerprint {}, the reference says {}",
            run.input_fnv,
            str_of(expect, "input_fnv")
        ));
    }
    if field(expect, "results") != &Value::Array(run.results.clone()) {
        return Some(format!(
            "operation results differ: expected {}, observed {}",
            field(expect, "results"),
            Value::Array(run.results.clone())
        ));
    }
    for point in field(expect, "checkpoints")
        .as_array()
        .expect("checkpoints")
    {
        let frame = usize::try_from(point[0].as_u64().expect("frame")).expect("frame");
        for (name, want, got) in [
            ("A", point[1].as_f64().expect("gain"), run.gain_a.get(frame)),
            ("B", point[2].as_f64().expect("gain"), run.gain_b.get(frame)),
        ] {
            match got {
                Some(&got) if (got - want).abs() <= GAIN_TOLERANCE => {}
                other => {
                    return Some(format!(
                        "frame {frame}: board {name} applied gain {other:?}, the reference says {want}"
                    ));
                }
            }
        }
    }
    let silent = run.gain_b.iter().filter(|&&g| g == 0.0).count() as u64;
    (silent != u64_of(expect, "silent_frames")).then(|| {
        format!(
            "{silent} silent frames, the reference says {}",
            u64_of(expect, "silent_frames")
        )
    })
}

fn problems(case: &Value, run: &Run) -> Vec<String> {
    let mut found = Vec::new();
    if run.role_mismatches != 0 {
        found.push(format!(
            "the role-mapped stream and the pre-mapped stream differ in {} samples",
            run.role_mismatches
        ));
    }
    for check in [
        against_expectation(case, run),
        regime(run),
        reference_peaks(run),
        linearity(run),
        silence(run),
        pairs(case, run),
    ] {
        found.extend(check);
    }
    found
}

fn load_vectors() -> Value {
    let path = std::env::var("FFW_G02_PCM_VECTORS").unwrap_or_else(|_| {
        format!(
            "{}/../../tests/g02/pcm_vectors.json",
            env!("CARGO_MANIFEST_DIR")
        )
    });
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!("cannot read G02 PCM vectors at {path}: {e} (generate: tests/g02/pcm_run.py --write-vectors)")
    });
    let doc: Value = serde_json::from_str(&text).expect("pcm_vectors.json parses");
    assert_eq!(doc["schema"], "ffw.g02.pcm.vectors.v1");
    doc
}

#[test]
fn g02_pcm_vectors_match_the_independent_reference() {
    let doc = load_vectors();
    let cases = doc["cases"].as_array().expect("cases array");
    assert!(cases.len() >= 8, "suspiciously few cases: {}", cases.len());
    let mut failures: Vec<String> = Vec::new();
    for case in cases {
        let run = run_case(case);
        println!("G02PCM-OBSERVED {}", observation(case, &run));
        for message in problems(case, &run) {
            let line = format!("{}: {message}", str_of(case, "id"));
            println!("G02PCM-DIVERGENCE {line}");
            failures.push(line);
        }
    }
    println!(
        "G02PCM-SUMMARY cases={} failures={}",
        cases.len(),
        failures.len()
    );
    assert!(
        failures.is_empty(),
        "{} G02 PCM problem(s); first: {}",
        failures.len(),
        failures[0]
    );
}

/// Control: each check is not vacuous. An unmodified run passes; a planted corruption of exactly the
/// thing a check protects must be reported, and only by the check that protects it.
#[test]
fn a_planted_defect_in_the_pcm_path_is_detected() {
    let doc = load_vectors();
    let case = doc["cases"]
        .as_array()
        .expect("cases")
        .iter()
        .find(|c| str_of(c, "id") == "G02PCM-004")
        .expect("the Left-room case exists");
    let run = run_case(case);
    assert_eq!(
        problems(case, &run),
        Vec::<String>::new(),
        "the unmodified run must pass"
    );

    let channels = run.channels;
    let loud = (1200..1500)
        .find(|&f| run.gain_b[f] == 0.0)
        .expect("the case has silent frames");

    let mut scaled = run.clone();
    scaled.out_b[1000 * channels + 2] += 3;
    assert!(
        linearity(&scaled).is_some(),
        "a 3 LSB error is a linearity violation"
    );
    assert!(silence(&scaled).is_none(), "and only a linearity one");

    let mut leaked = run.clone();
    leaked.out_b[loud * channels + 1] = 1;
    assert!(
        silence(&leaked).is_some(),
        "1 LSB while muted is not silence"
    );

    let mut stepped = run.clone();
    stepped.gain_b[1000] += 0.01;
    assert!(
        against_expectation(case, &stepped).is_some(),
        "a gain that is off by 0.01 at a checkpoint is detected"
    );

    let mut wrong_input = run.clone();
    wrong_input.input_fnv = "0000000000000000".to_string();
    assert!(against_expectation(case, &wrong_input).is_some());

    let mut limited = run.clone();
    limited.limiter_min = 0.9;
    assert!(
        regime(&limited).is_some(),
        "an engaged limiter invalidates the linear regime"
    );

    // A Left room whose two tweeters stopped matching: shift one channel of every pair by one LSB.
    let mut swapped = run.clone();
    for lane in swapped.out_a.chunks_exact_mut(channels) {
        lane[1] = lane[1].wrapping_add(1);
    }
    assert!(
        pairs(case, &swapped).is_some(),
        "a Left room whose pair differs is detected"
    );

    let mut mismatched = run;
    mismatched.role_mismatches = 1;
    assert!(!problems(case, &mismatched).is_empty());
}

/// The documented input: pins the first LCG samples (worked out on paper from the recurrence) and the
/// FNV-1a test vector, so a change to either breaks loudly.
#[test]
fn pcm_inputs_are_the_documented_lcg_stream() {
    // state1 = 1 * 1664525 + 1013904223 = 1015568748, and 1015568748 >> 16 = 15496; the sample is
    // 15496 / 32768 * 0.25 = 15496 / 131072. The next two states give raw 24200 and -32490. Written as
    // exact ratios (every value is a dyadic rational, exact in f32).
    let mut lcg = Lcg(1);
    assert_eq!(lcg.next_sample(), 15_496.0 / 131_072.0);
    assert_eq!(lcg.next_sample(), 24_200.0 / 131_072.0);
    assert_eq!(lcg.next_sample(), -32_490.0 / 131_072.0);
    assert_eq!(fnv_update(FNV_OFFSET, b""), 0xcbf2_9ce4_8422_2325);
    assert_eq!(fnv_update(FNV_OFFSET, b"a"), 0xaf63_dc4c_8601_ec8c);
    // Left and right use different seeds, so a Left room and a Right room are not the same signal.
    assert_ne!(Lcg(9).next_sample(), Lcg(10).next_sample());
}
